import type { OperationQueue, QueuedOperationBase } from '@arenile/shared/offline';

/**
 * Offline mode of the panel (spec 21.2, M5A): contract shared by the
 * offline cache, the operation queue and the features that enqueue.
 *
 * Decisions (ADR 0014):
 * - The service worker stays the one generated by vite-plugin-pwa
 *   (generateSW, configured in M0 in admin/vite.config.ts): it precaches the
 *   shell and static assets only. API responses are NEVER cached by the
 *   service worker (they are per user, per establishment and contain
 *   personal data); /api/ is excluded from the navigation fallback.
 * - Data for offline consultation lives in IndexedDB, written by the app
 *   (hand-written wrapper over the native API, no new dependency): the map
 *   documents and the bookings of today and tomorrow of the current
 *   establishment, refreshed while online, plus the configuration needed to
 *   render them and the signed-in user (to start the shell offline). Only
 *   the current establishment is kept; cleared on logout and when another
 *   user signs in; snapshots older than 48 hours are dropped (policy in
 *   cache.ts). The queue instead survives a change of user: it holds cash
 *   really collected and check-ins really made (no personal data), and the
 *   new session sends it.
 * - Only low-risk operations are queued offline: check-in, note, cash
 *   payment on an existing booking. Creating or moving bookings is never
 *   allowed offline (availability is guaranteed only by the server).
 * - On reconnection the queue is sent in order, one at a time, each with
 *   the Idempotency-Key generated at enqueue time (safe replays). Problem
 *   responses 409/412/422 mark the operation `conflict` and stop nothing
 *   else; they are shown to the user with the problem detail. 401 pauses the
 *   queue until the user logs in again. A check-in carries If-Match only
 *   when nothing else is queued on its booking (every queued operation
 *   raises the version on the server; the cached one follows, optimistic.ts).
 * - A connection indicator is always visible in the shell (online, offline,
 *   syncing with the count of pending operations, conflicts).
 */

/** Operation kinds allowed offline (spec 21.2). */
export type OfflineOperationKind = 'check_in' | 'note' | 'cash_payment';

export const OFFLINE_OPERATION_KINDS: readonly OfflineOperationKind[] = [
  'check_in',
  'note',
  'cash_payment',
];

/**
 * Fields common to every queued operation. id, idempotencyKey, createdAt,
 * seq, status and error are managed by the queue (shared/src/offline/queue.ts).
 */
interface OperationBase extends QueuedOperationBase {
  establishmentId: string;
  bookingId: string;
  /**
   * What the user sees in the queue list: spot label and booking code
   * (never the customer's contact details).
   */
  label: string;
}

/** POST bookings/{id}/check-in (If-Match with the cached version when known). */
export interface CheckInOperation extends OperationBase {
  kind: 'check_in';
  ifMatch?: string;
}

/** POST bookings/{id}/notes. */
export interface NoteOperation extends OperationBase {
  kind: 'note';
  text: string;
}

/** POST bookings/{id}/payments with method cash (needs an open cash session). */
export interface CashPaymentOperation extends OperationBase {
  kind: 'cash_payment';
  /** Integer cents. */
  amount: number;
  note?: string;
}

export type OfflineOperation = CheckInOperation | NoteOperation | CashPaymentOperation;

/** Connection state shown by the shell indicator. */
export type ConnectionState = 'online' | 'offline' | 'syncing';

/** Queue used by the features (created in runtime.ts on the shared queue). */
export type OfflineQueue = OperationQueue<OfflineOperation>;
